# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/41k_trust_extend_1979.R
# 41k_trust_extend_1979.R
# Extend the Ch3 political-trust series back to 1979 using the TrustGov
# (Tai 2026, Harvard Dataverse doi:10.7910/DVN/QRTOSI) UK latent trust series
# as a calibrated bridge for 1979-1985, where BSA (trust_v2.csv) has no data.
#
# PJ's decision (2 Sep 2026): treat the TrustGov-interpolated years as real
# data in the headline series, but attach heavy robustness checking (multiple
# calibration-window subsets + leave-one-out CV) and flag every interpolated
# year explicitly ("health warnings"), never silently blend it in.
#
# TrustGov's OWN raw UK input only has real observations at 1973, 1985, 1991,
# then 1997 onward (see sources_raw/trustgov_dataset/SOURCE_NOTE.md) — so even
# TrustGov's own 1979-1984 values are its model's random-walk interpolation
# between 1973 and 1985, not survey readings. We are one further step removed:
# calibrating BSA's % scale against TrustGov's latent theta scale using their
# overlap years (1986-2020), then reading off theta's already-interpolated
# 1979-1985 values through that calibration.
#
# OUTPUTS:
#   data/processed/trust_extended_1979_2024.csv   (combined series, flagged)
#   data/processed/trust_extend_calibration_robustness.csv (all specs' coefs + predictions)
#   figures/ch3_trust_extend_1979_robustness.png

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr, tibble, ggplot2, tidyr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT <- .ROOT
THETA_IN <- file.path(PROJECT, "../../sources_raw/trustgov_dataset/theta_summary.rda")
BSA_IN   <- file.path(PROJECT, "data/processed/trust_v2.csv")
OUT_CSV  <- file.path(PROJECT, "data/processed/trust_extended_1979_2024.csv")
OUT_ROB  <- file.path(PROJECT, "data/processed/trust_extend_calibration_robustness.csv")
OUT_FIG  <- file.path(PROJECT, "figures/ch3_trust_extend_1979_robustness.png")

NAVY <- "#1F3864"; RED <- "#d7191c"; GREY <- "#607D8B"; LIGHT_BLUE <- "#a6bddb"

# ============================================================
# 1. LOAD
# ============================================================
load(THETA_IN)  # -> theta_summary
theta_uk <- theta_summary |>
  filter(country == "United Kingdom", year >= 1979, year <= 2020) |>
  select(year, theta_mean = mean, theta_sd = sd) |>
  arrange(year)

bsa <- read_csv(BSA_IN, show_col_types = FALSE) |>
  select(year, trust_pct)

# Years where TrustGov's OWN raw input had a real UK observation (from
# sources_raw/trustgov_dataset/uk_raw_input_extract.tsv) — used for the
# "TrustGov-real-anchors-only" robustness spec below.
trustgov_real_years <- c(1973, 1985, 1991, 1997:2020)

overlap <- inner_join(theta_uk, bsa, by = "year")  # BSA years with a theta value
cat(sprintf("Overlap years for calibration: N = %d (%s)\n",
            nrow(overlap), paste(overlap$year, collapse = ", ")))

# ============================================================
# 2. CALIBRATION ROBUSTNESS — four specs on which overlap years anchor the fit
# ============================================================
specs <- list(
  "A. All overlap years"        = overlap,
  "B. Post-1990 only"           = overlap |> filter(year >= 1991),
  "C. Excl. crisis years"       = overlap |> filter(!year %in% c(2009, 2020)),
  "D. TrustGov real-anchors only" = overlap |> filter(year %in% trustgov_real_years)
)

all_years <- 1979:2020  # TrustGov's own coverage ceiling (Tai 2026 release stops at 2020)
target_years <- setdiff(all_years, bsa$year)  # every year without a real BSA reading
cat(sprintf("\nYears needing TrustGov-calibrated fill (no BSA reading, %d-%d): %s\n",
            min(all_years), max(all_years), paste(target_years, collapse = ", ")))
still_uncovered <- setdiff(1979:2025, union(all_years, bsa$year))
cat(sprintf("Years covered by NEITHER source (past TrustGov's 2020 ceiling, no BSA reading): %s\n",
            paste(still_uncovered, collapse = ", ")))

fit_and_predict <- function(d, spec_label) {
  m <- lm(trust_pct ~ theta_mean, data = d)
  pred <- tibble(year = target_years) |>
    left_join(theta_uk, by = "year") |>
    mutate(trust_pct_pred = predict(m, newdata = tibble(theta_mean = theta_mean)),
           spec = spec_label, n_anchor = nrow(d),
           r2 = summary(m)$r.squared,
           intercept = coef(m)[1], slope = coef(m)[2])
  pred
}

robustness <- bind_rows(lapply(names(specs), function(nm) fit_and_predict(specs[[nm]], nm)))

# Leave-one-out cross-validation of the baseline (spec A) calibration: how well
# does the calibration predict each held-out overlap year's REAL BSA value?
loo <- do.call(rbind, lapply(seq_len(nrow(overlap)), function(i) {
  train <- overlap[-i, ]
  test  <- overlap[i, ]
  m <- lm(trust_pct ~ theta_mean, data = train)
  pred <- predict(m, newdata = test)
  data.frame(year = test$year, observed = test$trust_pct, predicted = pred,
             error = pred - test$trust_pct)
}))
loo_rmse <- sqrt(mean(loo$error^2))
cat(sprintf("\nBaseline calibration LOO-CV RMSE: %.2f trust-pct points (N=%d overlap years)\n",
            loo_rmse, nrow(overlap)))
cat("LOO errors by year:\n")
print(loo)

write_csv(robustness, OUT_ROB)
cat(sprintf("\nRobustness table written: %s\n", OUT_ROB))
cat("\n=== Predicted 1979-1985 trust_pct under each calibration spec ===\n")
print(robustness |> select(spec, year, trust_pct_pred, n_anchor, r2) |>
        pivot_wider(names_from = spec, values_from = trust_pct_pred))

# ============================================================
# 3. FULL 1979-2020 SERIES, gap-free, EVERY spec's prediction retained
#    (PJ has not yet picked a headline spec — D has by far the best fit
#    (R2=0.67) and B is close behind (R2=0.52); A and C both lean on 1986/87,
#    which are themselves TrustGov-interpolated, not real, and fit badly
#    (R2<0.07). D is used for the single `trust_pct` column below as the
#    most defensible default, but all four are kept as their own columns
#    so nothing is hidden by that choice.)
# ============================================================
interp_wide <- robustness |>
  select(spec, year, theta_mean, pred = trust_pct_pred) |>
  pivot_wider(names_from = spec, values_from = pred) |>
  rename(
    pred_A_all_overlap   = `A. All overlap years`,
    pred_B_post1990      = `B. Post-1990 only`,
    pred_C_excl_crisis   = `C. Excl. crisis years`,
    pred_D_trustgov_real = `D. TrustGov real-anchors only`
  ) |>
  mutate(
    trust_pct = pred_D_trustgov_real,  # default/most-defensible spec — see note above
    is_trustgov_real_year = year %in% trustgov_real_years,
    data_source = "TrustGov-calibrated (INTERPOLATED)",
    note = ifelse(is_trustgov_real_year,
                   "HEALTH WARNING: BSA has no reading this year, but TrustGov's OWN input does — one step of interpolation, not two.",
                   "HEALTH WARNING: neither BSA nor TrustGov has a real reading this year — double-interpolated (TrustGov's random-walk, then this calibration).")
  )

observed <- bsa |>
  mutate(trust_pct_orig = trust_pct, data_source = "BSA 41 Table 3 (OBSERVED)", note = "",
         pred_A_all_overlap = NA_real_, pred_B_post1990 = NA_real_,
         pred_C_excl_crisis = NA_real_, pred_D_trustgov_real = NA_real_,
         is_trustgov_real_year = NA)

combined <- bind_rows(
  interp_wide |> select(year, trust_pct, data_source, note, is_trustgov_real_year,
                         pred_A_all_overlap, pred_B_post1990, pred_C_excl_crisis, pred_D_trustgov_real),
  observed |> select(year, trust_pct, data_source, note, is_trustgov_real_year,
                      pred_A_all_overlap, pred_B_post1990, pred_C_excl_crisis, pred_D_trustgov_real)
) |> arrange(year)

write_csv(combined, OUT_CSV)
cat(sprintf("\nCombined series written: %s (N=%d covering %d-%d, %d interpolated + %d observed)\n",
            OUT_CSV, nrow(combined), min(combined$year), max(combined$year),
            nrow(interp_wide), nrow(observed)))
if (length(still_uncovered) > 0) {
  cat(sprintf("STILL NOT COVERED by either source: %s (past TrustGov's 2020 ceiling, no BSA reading either)\n",
              paste(still_uncovered, collapse = ", ")))
}

# ============================================================
# 4. FIGURE — headline series with interpolated years visually distinct,
#    plus the robustness spread as a shaded band
# ============================================================
band <- robustness |>
  group_by(year) |>
  summarise(lo = min(trust_pct_pred), hi = max(trust_pct_pred), .groups = "drop")

p <- ggplot() +
  geom_ribbon(data = band, aes(x = year, ymin = lo, ymax = hi),
              fill = LIGHT_BLUE, alpha = 0.5) +
  geom_line(data = combined, aes(x = year, y = trust_pct, linetype = data_source),
            colour = NAVY, linewidth = 0.9) +
  geom_point(data = combined, aes(x = year, y = trust_pct, shape = data_source,
                                   colour = data_source), size = 2.2) +
  scale_colour_manual(values = c("BSA 41 Table 3 (OBSERVED)" = NAVY)) +
  scale_shape_manual(values = c(16, 1)) +
  labs(
    title    = "UK political trust, 1979-2020: BSA observed + TrustGov-calibrated gap fill",
    subtitle = paste0("Open circles = every year BSA didn't field (1979-1985 plus 14 gap years within ",
                       "1986-2024), calibrated from TrustGov's latent trust score — health warning: ",
                       "not observed data, default spec D (R2=0.67, see below).\n",
                       "Shaded band = spread across all four calibration-window robustness specs (",
                       "trust_extend_calibration_robustness.csv). ",
                       sprintf("%s uncovered by either source.",
                               if (length(still_uncovered) > 0)
                                 paste0(paste(still_uncovered, collapse = ", "), " remain")
                               else "No years remain")),
    x = NULL, y = "% trust govt 'just about always'/'most of the time' (calibrated scale)",
    caption = paste0(
      "Sources: BSA 41 Table 3 (1986-2024, observed, non-annual). Gap fill: TrustGov (Tai 2026, ",
      "Harvard Dataverse doi:10.7910/DVN/QRTOSI), UK latent trust score, calibrated to the BSA % ",
      sprintf("scale via linear regression, spec D (TrustGov real-anchor years only, N=%d, R2=0.67). ",
              nrow(specs[["D. TrustGov real-anchors only"]])),
      sprintf("Spec A (all %d overlap years) LOO-CV RMSE = %.1f pts, R2=0.07 — shown for contrast, ",
              nrow(overlap), loo_rmse),
      "not used as the default because it fits badly on exactly the years nearest the target period."
    )
  ) +
  theme_minimal(base_size = 11) +
  theme(legend.position = "bottom", legend.title = element_blank(),
        plot.caption = element_text(hjust = 0, size = 7, colour = GREY))

ggsave(OUT_FIG, p, width = 9, height = 6, dpi = 200)
cat(sprintf("Figure saved: %s\n", OUT_FIG))
